    # Get the row(s) and column(s) that have special colors
    special_rows = set(r for r, c in special_positions)
    special_cols = set(c for r, c in special_positions)

    # Within each special row/col, create alternating pattern
    # Use alternating A, B starting from the left/top

    for r in special_rows:
        for c in range(cols):
            if grid[r][c] in (A, B):
                # Find where in this row the sequence should be centered
                first_special = min(c for cns, c in special_positions if cns == r)
                dist = abs(c - first_special)
                output[r][c] = A if dist % 2 == 0 else B

    for c in special_cols:
