            counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1

    sorted_counts = sorted(counts.items(), key=lambda x: x[1], reverse=True)
    bg = sorted_counts[0][0]  # Most frequent = background

    # Get non-background colors sorted by value
    non_bg_colors = sorted([k for k in counts.keys() if k != bg])

    if len(non_bg_colors) < 1:
        return output

    C = non_bg_colors[-1]  # Use largest color as C (main/center)
    S = non_bg_colors[-2] if len(non_bg_colors) >= 2 else C  # Second is S (side)

    # Find all positions with special colors (C or S or any non-bg)
    special_cells = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                special_cells.add((r, c))

    if not special_cells:
        return output

    # Find bounding box of all special cells
    min_r, max_r = min(p[0] for p in special_cells), max(p[0] for p in special_cells)
    min_c, max_c = min(p[1] for p in special_cells), max(p[1] for p in special_cells)

    # Center of bounding box
    center_r = (min_r + max_r) // 2
    center_c = (min_c + max_c) // 2

    # For each cell on special rows/cols, apply alternating pattern
    # p=C when Manhattan distance from center is even, p=S when odd
    for r in range(rows):
        for c in range(cols):
            # Check if cell is on a special row or column, but within bounding box
            if (r == center_r or c == center_c) and min_r <= r <= max_r + 3 and min_c <= c <= max_c + 3:
                dist = abs(r - center_r) + abs(c - center_c)
                if dist % 2 == 0:
                    output[r][c] = C
                else:
                    output[r][c] = S

    return output
